import 'package:flutter/material.dart';
import '../../services/api_service.dart';

class GroupsScreen extends StatefulWidget { const GroupsScreen({super.key}); @override State<GroupsScreen> createState()=>_GroupsScreenState(); }
class _GroupsScreenState extends State<GroupsScreen>{
 List<dynamic> groups=[],students=[],teachers=[],supervisors=[]; List<String> subjects=[]; bool loading=true;
 static const fallback=['العربية','اللغة الإنجليزية','الرياضيات','العلوم','الدراسات الاجتماعية','Math','Science','English','Arabic','German','French','Spanish','Quran'];
 List<dynamic> list(dynamic v){if(v is List)return List<dynamic>.from(v);if(v is Map){final d=v['data'];if(d is List)return List<dynamic>.from(d);if(d is Map&&d['data'] is List)return List<dynamic>.from(d['data']);}return[];}
 int id(dynamic v)=>int.tryParse('${v['id']}')??0; String sub(dynamic v)=>v is Map?'${v['subject']??v['name']??''}':'$v'; void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));
 @override void initState(){super.initState();load();}
 Future<void> load()async{if(mounted)setState(()=>loading=true);Object? error;try{final r=await ApiService.get('groups');if(mounted)setState(()=>groups=list(r));}catch(e){error=e;}try{final r=await ApiService.get('students');if(mounted)setState(()=>students=list(r));}catch(_){ }try{final r=await ApiService.get('teachers');if(mounted)setState(()=>teachers=list(r));}catch(_){ }try{final r=await ApiService.get('subjects');final s=list(r).map(sub).where((x)=>x.isNotEmpty).toSet().toList();if(mounted)setState(()=>subjects=s.isEmpty?fallback:s);}catch(_){if(mounted)setState(()=>subjects=fallback);}try{final r=await ApiService.get('supervisors');if(mounted)setState(()=>supervisors=list(r));}catch(_){ }if(mounted){setState(()=>loading=false);if(error!=null)msg(error!);}}
 Future<void> form()async{if(teachers.isEmpty){msg(Exception('أضف مدرسًا أولًا.'));return;}if(students.isEmpty){msg(Exception('أضف طالبًا أولًا.'));return;}int? teacherId=id(teachers.first);String subject=subjects.isEmpty?fallback.first:subjects.first;final name=TextEditingController(),rate=TextEditingController();final selected=<int>{};final key=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(dialog)=>StatefulBuilder(builder:(context,set)=>AlertDialog(title:const Text('إنشاء مجموعة'),content:SizedBox(width:500,child:SingleChildScrollView(child:Form(key:key,child:Column(children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'اسم المجموعة *'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),DropdownButtonFormField<int>(value:teacherId,decoration:const InputDecoration(labelText:'المدرس'),items:teachers.map((t)=>DropdownMenuItem(value:id(t),child:Text('${t['name']}'))).toList(),onChanged:(v){if(v!=null)set(()=>teacherId=v);}),DropdownButtonFormField<String>(value:subject,decoration:const InputDecoration(labelText:'المادة'),items:(subjects.isEmpty?fallback:subjects).map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v){if(v!=null)set(()=>subject=v);}),TextFormField(controller:rate,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'سعر الحصة *'),validator:(v)=>double.tryParse(v??'')==null?'أدخل السعر':null),const SizedBox(height:8),...students.map((s){final sid=id(s);return CheckboxListTile(value:selected.contains(sid),title:Text('${s['name']}'),onChanged:(v){set((){if(v==true){selected.add(sid);}else{selected.remove(sid);}});});}).toList()])))),actions:[TextButton(onPressed:()=>Navigator.pop(dialog,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(key.currentState!.validate()&&selected.isNotEmpty)Navigator.pop(dialog,true);},child:const Text('حفظ'))]));if(ok==true){try{await ApiService.post('groups',{'name':name.text.trim(),'subject':subject,'teacher_id':teacherId,'teacher_rate':double.parse(rate.text),'student_ids':selected.toList(),'status':'active'});await load();}catch(e){msg(e);}}rate.dispose();name.dispose();}
 Future<void> remove(dynamic g)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('حذف المجموعة'),content:Text('حذف ${g['name']??''}؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('groups/${id(g)}');await load();}catch(e){msg(e);}}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المجموعات'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:form,icon:const Icon(Icons.groups),label:const Text('إنشاء مجموعة')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:groups.isEmpty?ListView(children:const[SizedBox(height:180),Center(child:Text('لا توجد مجموعات بعد.'))]):ListView.builder(padding:const EdgeInsets.fromLTRB(16,12,16,90),itemCount:groups.length,itemBuilder:(_,i){final g=Map<String,dynamic>.from(groups[i]);return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.groups)),title:Text('${g['name']??''}'),subtitle:Text('المدرس: ${g['teacher']?['name']??''}\nالمادة: ${g['subject']??''} • الطلاب: ${g['students_count']??0}'),isThreeLine:true,trailing:IconButton(onPressed:()=>remove(g),icon:const Icon(Icons.delete))));})));}
